source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # The repeated horizontal color key is three identical rows.
    row_counts = {}
    for r, row in enumerate(grid):
        key = tuple((c, v) for c, v in enumerate(row) if v)
        if key:
            row_counts.setdefault(key, []).append(r)
    stripe_key, stripe_rows = max(row_counts.items(), key=lambda item: (len(item[1]), len(item[0])))
    palette = [v for c, v in stripe_key]
    marker = set()
    if len(stripe_rows) >= 3:
        marker = {(r, c) for r in stripe_rows for c, v in stripe_key}

    pixels = {(r, c): grid[r][c] for r in range(h) for c in range(w)
              if grid[r][c] and (r, c) not in marker}
    rows = sorted({r for r, c in pixels})
    top, bottom = rows[0], rows[-1]
    height = bottom - top + 1
    profiles = [tuple(c for r, c in pixels if r == y) for y in range(top, bottom + 1)]
    unit = height
    for p in range(1, height + 1):
        if height % p == 0 and all(profiles[i] == profiles[i % p] for i in range(height)):
            unit = p
            break

    # Align the repeated motif using the location of any color already in the key.
    origins = []
    for i, color in enumerate(palette):
        rs = [r for (r, c), v in pixels.items() if v == color]
        if rs:
            origins.append(min(rs) - i * unit)
    origin = origins[0] if origins else top

    motif = [[0] * w for _ in range(unit)]
    for (r, c), color in pixels.items():
        motif[(r - top) % unit][c] = 1
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        for dr in range(unit):
            y = origin + i * unit + dr
            if 0 <= y < h:
                for c, occupied in enumerate(motif[dr]):
                    if occupied:
                        out[y][c] = color
    return out
'''
